# small helper
import math, statistics
def test_matches_statistics():
    import random
    random.seed(0)
    for _ in range(5):
        n1, n2 = random.randint(0,8), random.randint(0,8)
        a = sorted(random.randint(-50,50) for _ in range(n1))
        b = sorted(random.randint(-50,50) for _ in range(n2))
        expected = statistics.median(a + b)
        got = f(a, b)
        assert abs(got - expected) < 1e-6, (a, b, got, expected)

